# Writes picks.json for the feature panel mock-ups.
import json, os
def frames(code, x, caps):
    out = []
    for state, cap in caps:
        f = f"{code}-{x}-{state}.html"
        assert os.path.exists("frames/" + f), f
        out.append({"file": f, "caption": cap})
    return out

