def props(code, d):
    out = []
    for x, (name, rec, what, why, plus, cost, caps) in d.items():
        p = {"letter": x.upper(), "name": name, "recommended": rec, "what": what}
        if rec: p["why"] = why
        p.update({"plus": plus, "cost": cost, "frames": frames(code, x, caps)})
        out.append(p)
    assert sum(p["recommended"] for p in out) == 1
    return out
